// Pure deterministic teaching traces. Frames are snapshots, independent of the renderer.
export const animations = [];
const registry = new Map();
const clone = x => JSON.parse(JSON.stringify(x));
const range = (n, start=0) => Array.from({length:Math.max(0,n)},(_,i)=>i+start);
function add(id,title,docs,fn) { animations.push({id,title,docs}); registry.set(id,fn); }
export function frames(id,input=[8,3,6,1,7,4,2,5]) {
  const fn=registry.get(id); if(!fn) throw new Error('未实现的动画：'+id);
  const a=input.slice(0,12).filter(Number.isFinite);
  return fn(a.length?a:[8,3,6,1,7,4,2,5]);
}
function arrayTrace(a){const out=[];return {out,step:(text,active=[],vars={},done=[])=>out.push(clone({values:a,active,done,text,vars}))};}
function finished(t,a,text='排序完成，所有相邻元素均满足非降序。'){t.step(text,[],{},range(a.length));return t.out;}
add('insertion-sort','直接插入排序',['插入排序'],a=>{
 const t=arrayTrace(a);t.step('左侧维护已排序前缀，从下标 1 开始取待插入元素。');
 for(let i=1;i<a.length;i++){const key=a[i];let j=i-1;t.step('暂存待插入值，向左寻找插入位置。',[i],{i,key});
 while(j>=0&&a[j]>key){a[j+1]=a[j];t.step('前面的值更大，向右移动一格。',[j,j+1],{i,j,key});j--;}
 a[j+1]=key;t.step('把暂存值放入空位；已排序前缀扩大。',[j+1],{i,key},range(i+1));}return finished(t,a);
});
add('shell-sort','希尔排序',['插入排序'],a=>{const t=arrayTrace(a);t.step('先按较大间隔分组，逐步缩小间隔。');
 for(let gap=Math.floor(a.length/2);gap>0;gap=Math.floor(gap/2)){t.step('开始处理 gap='+gap+' 的各个子序列。',[],{gap});
 for(let i=gap;i<a.length;i++){let key=a[i],j=i;while(j>=gap&&a[j-gap]>key){a[j]=a[j-gap];t.step('同一组内把更大的值向后移动 gap 格。',[j-gap,j],{gap,key});j-=gap;}a[j]=key;t.step('完成当前元素的分组插入。',[j],{gap,key});}}return finished(t,a);});
add('bubble-sort','冒泡排序',['交换排序'],a=>{const t=arrayTrace(a);t.step('比较相邻元素，把较大者逐步推到右端。');
 for(let end=a.length-1;end>0;end--){for(let j=0;j<end;j++){t.step('比较相邻两个值。',[j,j+1],{end,j},range(a.length-end-1,end+1));if(a[j]>a[j+1]){[a[j],a[j+1]]=[a[j+1],a[j]];t.step('左值更大，交换。',[j,j+1],{end,j},range(a.length-end-1,end+1));}}t.step('本轮最大值已到达最终位置。',[end],{end},range(a.length-end,end));}return finished(t,a);});
add('selection-sort','直接选择排序',['选择排序'],a=>{const t=arrayTrace(a);t.step('每轮在未排序区间中寻找最小值。');
 for(let i=0;i<a.length;i++){let k=i;for(let j=i+1;j<a.length;j++){t.step('比较当前候选与新元素。',[k,j],{i,j,minIndex:k},range(i));if(a[j]<a[k]){k=j;t.step('更新最小值候选。',[k],{i,minIndex:k},range(i));}}[a[i],a[k]]=[a[k],a[i]];t.step('把本轮最小值放到有序前缀末端。',[i,k],{i},range(i+1));}return finished(t,a);});
add('quick-sort','快速排序',['交换排序'],a=>{const t=arrayTrace(a);t.step('演示 Lomuto 分区：暂把末尾元素作为基准，再递归两侧。');const done=new Set();
 function sort(l,r){if(l>r)return;if(l===r){done.add(l);return;}const pivot=a[r];let p=l;t.step('选择当前区间的基准。',[r],{left:l,right:r,pivot},[...done]);
 for(let j=l;j<r;j++){t.step('检查元素是否小于基准。',[j,r],{left:l,right:r,j,boundary:p,pivot},[...done]);if(a[j]<pivot){[a[p],a[j]]=[a[j],a[p]];t.step('较小元素放入左区。',[p,j],{boundary:p,pivot},[...done]);p++;}}
 [a[p],a[r]]=[a[r],a[p]];done.add(p);t.step('基准归位；两边还需分别排序。',[p],{pivot,index:p},[...done]);sort(l,p-1);sort(p+1,r);}sort(0,a.length-1);return finished(t,a);});
function heapTrace(a,sortMode){const t=arrayTrace(a);let n=a.length;
 function down(i,size){for(;;){let k=i,l=2*i+1,r=l+1;if(l<size&&a[l]>a[k])k=l;if(r<size&&a[r]>a[k])k=r;t.step('检查父结点与有效堆内的孩子。',[i,l,r].filter(x=>x<size),{root:i,heapSize:size},range(n-size,size));if(k===i)break;[a[i],a[k]]=[a[k],a[i]];t.step('与较大的孩子交换，继续下沉。',[i,k],{heapSize:size},range(n-size,size));i=k;}}
 t.step('把数组看成完全二叉树，从最后一个非叶结点自底向上建大顶堆。');for(let i=Math.floor(n/2)-1;i>=0;i--)down(i,n);t.step('建堆完成：每个父结点都不小于孩子，堆顶为最大值。',[0],{heap:a.join(',')});
 if(sortMode){for(let end=n-1;end>0;end--){[a[0],a[end]]=[a[end],a[0]];t.step('堆顶与最后一个有效元素交换，该最大值归位。',[0,end],{heapSize:end},range(n-end,end));down(0,end);}return finished(t,a);}
 return t.out;}
add('heap-sort','堆排序',['选择排序','堆'],a=>heapTrace(a,true));
add('heap','二叉堆：自底向上建堆',['堆','STL的堆','完全二叉树'],a=>heapTrace(a,false));
add('merge-sort','归并排序',['归并排序','LIST','课后习题','练习'],a=>{const t=arrayTrace(a);t.step('先递归拆分，再从最短的有序段开始归并。');
 function sort(l,r){if(r-l<=1)return;let m=Math.floor((l+r)/2);t.step('拆分成左右两个半开区间。',range(r-l,l),{left:l,mid:m,right:r});sort(l,m);sort(m,r);let i=l,j=m,tmp=[];
 while(i<m||j<r){let from=(j>=r||(i<m&&a[i]<=a[j]))?i++:j++;tmp.push(a[from]);t.step('把两段剩余首元素中较小的取到辅助数组。',[from],{left:l,mid:m,right:r,tmp:tmp.join(',')});}for(let k=0;k<tmp.length;k++)a[l+k]=tmp[k];t.step('将归并结果复制回原区间。',range(r-l,l),{left:l,right:r});}sort(0,a.length);return finished(t,a);});
add('counting-sort','计数排序',['分配类排序'],a=>{const t=arrayTrace(a),min=Math.min(...a),max=Math.max(...a);t.step('按数值统计频次；下标用 值-min，支持负数。',[],{min,max});const counts=new Map();for(let i=0;i<a.length;i++){counts.set(a[i],(counts.get(a[i])||0)+1);t.step('统计当前值出现次数。',[i],{count:[...counts].sort((x,y)=>x[0]-y[0]).map(([v,c])=>v+':'+c).join(' ')});}let k=0;for(const [value,count]of [...counts].sort((x,y)=>x[0]-y[0]))for(let c=0;c<count;c++){a[k]=value;t.step('按键值递增顺序收集元素。',[k],{value,write:k},range(k));k++;}return finished(t,a);});
add('radix-sort','基数排序（LSD）',['分配类排序'],a=>{const t=arrayTrace(a);const min=Math.min(...a);const offset=min<0?-min:0;let keyed=a.map(v=>({value:v,key:v+offset}));t.step('从最低位开始稳定分组；负数先统一加偏移，排序关系不变。',[],{offset});let max=Math.max(...keyed.map(x=>x.key));if(!a.every(Number.isSafeInteger)){t.step('本演示只处理安全整数；小数需先定义位表示方法。');return t.out;}for(let digit=1;digit<=max;digit*=10){const buckets=range(10).map(()=>[]);for(let i=0;i<keyed.length;i++){const b=Math.floor(keyed[i].key/digit)%10;buckets[b].push(keyed[i]);t.step('按当前数位放入桶；同桶维持原先顺序。',[i],{digit,bucket:b,buckets:buckets.map((x,k)=>k+':'+x.map(y=>y.value).join(',')).join(' | ')});}keyed=buckets.flat();a.splice(0,a.length,...keyed.map(x=>x.value));t.step('从桶 0 到桶 9 稳定收集。',[],{digit});if(digit>Number.MAX_SAFE_INTEGER/10)break;}return finished(t,a);});
add('bucket-sort','桶排序',['分配类排序'],a=>{const t=arrayTrace(a),min=Math.min(...a),max=Math.max(...a),buckets=range(4).map(()=>[]);t.step('把值域划成 4 个桶，先分配，再各桶排序。');for(let i=0;i<a.length;i++){let b=max===min?0:Math.min(3,Math.floor((a[i]-min)/(max-min)*4));buckets[b].push(a[i]);t.step('放入对应值域的桶。',[i],{bucket:b,buckets:buckets.map(x=>x.join(',')).join(' | ')});}let pos=0;for(let b=0;b<4;b++){buckets[b].sort((x,y)=>x-y);for(const v of buckets[b])a[pos++]=v;t.step('桶内排好后按桶号依次收集。',range(buckets[b].length,pos-buckets[b].length),{bucket:b},range(pos));}return finished(t,a);});
add('linear-search','顺序查找',['算法','顺序表','线性表查找'],a=>{const t=arrayTrace(a),target=a[Math.floor(a.length*2/3)];t.step('从左到右逐个检查，本次目标为 '+target,[],{target});for(let i=0;i<a.length;i++){t.step('比较当前位置与目标。',[i],{i,target});if(a[i]===target){t.step('找到第一个相等元素，返回下标。',[i],{index:i,target},[i]);break;}}return t.out;});
add('binary-search','二分查找',['算法','线性表查找','判定树'],a=>{a.sort((x,y)=>x-y);const t=arrayTrace(a),target=a[Math.floor(a.length*2/3)];let l=0,r=a.length-1;t.step('已将输入升序排序，目标为 '+target,[],{target});while(l<=r){const mid=l+Math.floor((r-l)/2);t.step('比较中点，下一步排除不可能的一半。',[mid],{left:l,right:r,mid,target});if(a[mid]===target){t.step('找到目标，返回该下标（重复值时不保证最左）。',[mid],{index:mid},[mid]);break;}if(a[mid]<target)l=mid+1;else r=mid-1;t.step('更新仍可能包含目标的闭区间。',range(r-l+1,l),{left:l,right:r});}return t.out;});
add('array-insert','顺序表插入',['数据结构','线性表','顺序表','vector'],a=>{const t=arrayTrace(a),pos=Math.floor(a.length/2),value=6;let n=a.length;t.step('在中间位置插入 6，需要先向右挪出空位。',[],{pos,value,length:n});a.push(0);for(let i=n;i>pos;i--){a[i]=a[i-1];t.step('从后往前搬移，避免覆盖尚未搬走的值。',[i-1,i],{i,pos});}a[pos]=value;t.step('写入新值并增加长度。',[pos],{length:a.length});return t.out;});
